import json, sys
import boto3
from botocore.exceptions import ClientError

# A step with no cloud integration bound reaches signing time and raises
# NoCredentialsError as a bare traceback. The agent would then file that
# traceback as an observation. Fail here instead, with a sentence that names
# what is missing and who fixes it.
_creds = boto3.session.Session().get_credentials()
if _creds is None:
    print(json.dumps({"error": "No AWS credentials reached this step. Bind an AWS cloud "
                               "integration to this automation under Cloud Integrations, "
                               "and make sure it is available to this project."}))
    raise SystemExit(1)

REGION = "{{Region}}"
s3 = boto3.session.Session(region_name=REGION).client("s3")


def public_reasons(bucket):
    """Every distinct way this bucket is reachable by the public. Read-only."""
    reasons = []

    # The public access block OVERRIDES policy and ACL, so its absence is what
    # makes the other two findings matter rather than being theoretical.
    try:
        cfg = s3.get_public_access_block(Bucket=bucket)["PublicAccessBlockConfiguration"]
        off = sorted(k for k, v in cfg.items() if not v)
        if off:
            reasons.append("public access block incomplete: " + ", ".join(off))
    except ClientError as e:
        code = e.response["Error"]["Code"]
        if code == "NoSuchPublicAccessBlockConfiguration":
            reasons.append("no public access block configured at all")
        else:
            reasons.append("public access block unreadable (" + code + ")")

    try:
        if s3.get_bucket_policy_status(Bucket=bucket)["PolicyStatus"]["IsPublic"]:
            reasons.append("bucket policy grants public access")
    except ClientError as e:
        if e.response["Error"]["Code"] != "NoSuchBucketPolicy":
            reasons.append("policy status unreadable (" + e.response["Error"]["Code"] + ")")

    try:
        for grant in s3.get_bucket_acl(Bucket=bucket).get("Grants", []):
            uri = grant.get("Grantee", {}).get("URI", "")
            if uri.endswith("/AllUsers"):
                reasons.append("ACL grants " + str(grant.get("Permission")) + " to everyone")
            elif uri.endswith("/AuthenticatedUsers"):
                reasons.append("ACL grants " + str(grant.get("Permission"))
                               + " to any AWS account")
    except ClientError as e:
        reasons.append("ACL unreadable (" + e.response["Error"]["Code"] + ")")

    return reasons


out = {"region": REGION, "buckets": [], "errors": []}
try:
    buckets = s3.list_buckets().get("Buckets", [])
except ClientError as e:
    print(json.dumps({"error": "could not list buckets: " + str(e)}))
    sys.exit(1)

for b in buckets:
    name = b["Name"]
    try:
        loc = s3.get_bucket_location(Bucket=name).get("LocationConstraint") or "us-east-1"
    except ClientError:
        loc = "unknown"
    try:
        reasons = public_reasons(name)
    except Exception as exc:            # one bad bucket must not end the audit
        out["errors"].append({"bucket": name, "error": str(exc)})
        continue
    out["buckets"].append({
        "name": name,
        "region": loc,
        "created": b["CreationDate"].isoformat(),
        "public": bool(reasons),
        "reasons": reasons,
    })

out["summary"] = {
    "total": len(out["buckets"]),
    "public": sum(1 for x in out["buckets"] if x["public"]),
    "unreadable": len(out["errors"]),
}
print(json.dumps(out, indent=2))
